struct Sample {int lane,tick,sub;std::vector<float> q,v;std::array<float,24> expected;std::array<double,3> com;std::array<std::array<double,3>,4> pos;};
int main(int argc,char**argv){@autoreleasepool{try{
 need(argc==2,"expected metallib path");RunManifest m;m.id="crow_fixed_state_aero_probe";m.robot=hipRollModel();need(m.robot.mechanics.joints.at(5).axis0.y==-1.f,"unexpected right axis");m.robot.mechanics.joints.at(5).axis0.y=1.f;m.scene=makeBirdFlowAmericanCrowFlightScenePack();m.sensors.id="proprioception";m.task=makeAmericanCrowEmbodiedTaskPack(m.sensors.observation,m.reality.reset);m.reality.reset={};m.reality.id="reality";m.teacher.id="no_teacher";m.profile.id="probe";m.profile.capacities={.candidatePairs=512,.rawContacts=2048,.manifolds=512,.constraintBlocks=2048,.constraintRows=6144};m.task.capacities=m.profile.capacities;m.profile.environmentCount=1;m.profile.controlSteps=1;m.profile.physicsSubsteps=16;m.profile.controlTimestepSeconds=.02f;CompiledRun run;auto built=compileRun(m,run);need(built.succeeded(),"compileRun: "+built.message);auto* prog=run.flappingWingProgram();need(prog&&prog->valid(),"flapping program unavailable");const auto& model=run.model();const unsigned nq=model.defaultQ.size(),nv=model.defaultV.size(),nb=model.bodies.size();need(nq==41 && nv==40 && nb==36,"unexpected compiled model sizes");need(model.bodyNames.at(0)=="crow_body" && model.bodyNames.at(5)=="crow_left_wing" && model.bodyNames.at(6)=="crow_right_wing" && model.bodyNames.at(7)=="crow_tail","unexpected aero body mapping");
 std::vector<Sample> samples;int lane,tick,sub;while(std::cin>>lane>>tick>>sub){Sample s{};s.lane=lane;s.tick=tick;s.sub=sub;s.q.resize(nq);s.v.resize(nv);for(auto&x:s.q)need(bool(std::cin>>x),"truncated q");for(auto&x:s.v)need(bool(std::cin>>x),"truncated v");for(auto&x:s.expected)need(bool(std::cin>>x),"truncated expected");std::vector<double>qd(s.q.begin(),s.q.end()),vd(s.v.begin(),s.v.end());std::vector<ArticulatedBodyKinematics> k(model.articulations[0].bodyCount);need(computeArticulatedBodyKinematics(model,0,qd,vd,k).succeeded(),"FK failed");double mass=0;for(unsigned b=0;b<k.size();b++){double w=model.bodies[b].massAndInverseMass.x;mass+=w;for(int j=0;j<3;j++)s.com[j]+=w*k[b].centerOfMassPosition[j];}need(mass>0,"bad mass");for(auto&x:s.com)x/=mass;for(int j=0;j<4;j++){unsigned b=std::array<unsigned,4>{0,5,6,7}[j];for(int i=0;i<3;i++)s.pos[j][i]=k[b].centerOfMassPosition[i];}samples.push_back(std::move(s));}need(samples.size()==4032,"unexpected input count");const NSUInteger n=samples.size();id<MTLDevice> device=MTLCreateSystemDefaultDevice();need(device!=nil,"Metal device unavailable");NSError* error=nil;NSString* path=[NSString stringWithUTF8String:argv[1]];id<MTLLibrary> lib=[device newLibraryWithFile:path error:&error];need(lib!=nil,std::string("metallib: ")+(error?[[error localizedDescription] UTF8String]:"unknown"));id<MTLFunction> f=[lib newFunctionWithName:@"mr_step_compiled_flapping_wings"];need(f!=nil,"aero kernel missing");id<MTLComputePipelineState> pipe=[device newComputePipelineStateWithFunction:f error:&error];need(pipe!=nil,"pipeline failed");id<MTLCommandQueue> queue=[device newCommandQueue];need(queue!=nil,"queue failed");
 std::vector<float> qs(n*nq),vs(n*nv);for(NSUInteger i=0;i<n;i++){std::copy(samples[i].q.begin(),samples[i].q.end(),qs.begin()+i*nq);std::copy(samples[i].v.begin(),samples[i].v.end(),vs.begin()+i*nv);}const std::array<float,5> left={0.f,.02f,-.02f,.02f,-.02f},right={0.f,-.02f,.02f,.02f,-.02f};const unsigned bodies[4]={0,5,6,7};double maxErr=0,sumErr2=0;unsigned long long nErr=0;std::cout<<std::setprecision(12);
 for(unsigned c=0;c<5;c++){auto q=qs;auto v=vs;for(NSUInteger i=0;i<n;i++){q[i*nq+11]+=left[c];q[i*nq+12]+=right[c];need(std::abs(q[i*nq+11])<=.35 && std::abs(q[i*nq+12])<=.35,"pronation limit");}id<MTLBuffer> qb=[device newBufferWithBytes:q.data() length:q.size()*sizeof(float) options:MTLResourceStorageModeShared];need(qb!=nil,"q buffer failed");id<MTLBuffer> vb=[device newBufferWithBytes:v.data() length:v.size()*sizeof(float) options:MTLResourceStorageModeShared];id<MTLBuffer> wb=[device newBufferWithLength:n*nb*sizeof(MRABABodyWrenchGPU) options:MTLResourceStorageModeShared];need(vb!=nil && wb!=nil,"buffer failed");std::memset(wb.contents,0,wb.length);MRCompiledFlappingWingDispatchGPU d{};d.environmentCount=n;d.qStride=nq;d.vStride=nv;d.bodyStride=nb;d.qOffset=model.articulations[0].qOffset;d.vOffset=model.articulations[0].vOffset;d.rootBodyIndex=prog->rootBodyIndex;d.windVelocityAndDensity=prog->windVelocityAndDensity;id<MTLCommandBuffer> cb=[queue commandBuffer];id<MTLComputeCommandEncoder> enc=[cb computeCommandEncoder];need(cb!=nil && enc!=nil,"command failed");[enc setComputePipelineState:pipe];[enc setBytes:prog->wings.data() length:sizeof(MRFlappingWingGPU)*2 atIndex:0];[enc setBytes:&d length:sizeof(d) atIndex:1];[enc setBuffer:qb offset:0 atIndex:2];[enc setBuffer:vb offset:0 atIndex:3];[enc setBuffer:wb offset:0 atIndex:4];[enc setBytes:&prog->tail length:sizeof(prog->tail) atIndex:5];[enc setBytes:&prog->fuselage length:sizeof(prog->fuselage) atIndex:6];[enc dispatchThreads:MTLSizeMake(n,1,1) threadsPerThreadgroup:MTLSizeMake(std::min<NSUInteger>(64,pipe.maxTotalThreadsPerThreadgroup),1,1)];[enc endEncoding];[cb commit];[cb waitUntilCompleted];need(cb.status==MTLCommandBufferStatusCompleted,"GPU dispatch failed");const auto* out=static_cast<const MRABABodyWrenchGPU*>(wb.contents);
  for(NSUInteger i=0;i<n;i++){std::vector<double> qd(q.begin()+i*nq,q.begin()+(i+1)*nq),vd(v.begin()+i*nv,v.begin()+(i+1)*nv);std::vector<ArticulatedBodyKinematics> k(model.articulations[0].bodyCount);need(computeArticulatedBodyKinematics(model,0,qd,vd,k).succeeded(),"perturbed FK failed");std::array<double,3> com{};double mass=0;for(unsigned b=0;b<k.size();b++){double w=model.bodies[b].massAndInverseMass.x;mass+=w;for(int j=0;j<3;j++)com[j]+=w*k[b].centerOfMassPosition[j];}for(auto&x:com)x/=mass;std::array<double,3> force{},moment{};for(unsigned j=0;j<4;j++){const auto&w=out[i*nb+bodies[j]];float v6[]={w.force.x,w.force.y,w.force.z,w.torque.x,w.torque.y,w.torque.z};for(int h=0;h<6;h++){need(std::isfinite(v6[h]),"nonfinite wrench");if(c==0){double err=std::abs(v6[h]-samples[i].expected[j*6+h]);maxErr=std::max(maxErr,err);sumErr2+=err*err;nErr++;}}double rx=k[bodies[j]].centerOfMassPosition[0]-com[0],ry=k[bodies[j]].centerOfMassPosition[1]-com[1],rz=k[bodies[j]].centerOfMassPosition[2]-com[2];force[0]+=w.force.x;force[1]+=w.force.y;force[2]+=w.force.z;moment[0]+=w.torque.x+ry*w.force.z-rz*w.force.y;moment[1]+=w.torque.y+rz*w.force.x-rx*w.force.z;moment[2]+=w.torque.z+rx*w.force.y-ry*w.force.x;}std::cout<<c<<" "<<samples[i].lane<<" "<<samples[i].tick<<" "<<samples[i].sub;for(auto x:force)std::cout<<" "<<x;for(auto x:moment)std::cout<<" "<<x;std::cout<<"\n";}}
 std::cerr<<std::setprecision(12)<<"baseline_max_abs_error "<<maxErr<<" baseline_rms_error "<<std::sqrt(sumErr2/nErr)<<" n "<<nErr<<"\n";return 0;
 }catch(const std::exception&e){std::cerr<<"failure "<<e.what()<<"\n";return 1;}}}
